task.errors:
PROMPT_BUILD_FAILED(из M-03); LLM_FAILED(из M-04); OUTPUT_UNPARSEABLE;
                LOG_IO_ERROR(из M-05 — потеря лога ломает NFR-04, не глотаем);
                WIKI_PAGE_NOT_FOUND / WIKI_PAGE_INVALID / WIKI_BUNDLE_TOO_LARGE (из M-16)

PACKAGE_TARGET_EXISTS(каталог непуст); PACKAGE_NO_CODE_ARTIFACT(code_node);
                PACKAGE_NO_RUN_LOG(путь); NO_FILE_BLOCKS(из TSK-1102);
                FREEZE_FAILED(pip freeze exit≠0); PACKAGE_IO_ERROR;
                GIT_FAILED(git отсутствует или коммит не прошёл); + ошибки M-10

task.outputs:
Result[AcceptanceReport(matched[], mismatched[], missing[])];
                 файл в нескольких записях → действует hash ПОЗДНЕЙ (свежая приёмка);
                 значение `removed` вместо hash снимает путь с проверки
                 (переезд/удаление файла фиксируется записью, а не правкой истории)

task.errors:
PRODUCT_TARGET_EXISTS; SERVICE_PACKAGE_NOT_FOUND(имя);
                SERVICE_NO_DOCKERFILE(имя — пакет без serve не собирается в продукт);
                PRODUCT_IO_ERROR; GIT_FAILED

task.outputs:
Result[str] — страницы с разделителями "=== wiki: путь ==="
                 в порядке refs; дубликат пути включается один раз;
                 пустой refs → Ok("")

task.errors:
WIKI_PAGE_NOT_FOUND; WIKI_PAGE_INVALID(путь — литеральные "{{"
                уронят сборку M-03 ошибкой UNRESOLVED_PLACEHOLDER, ловим раньше);
                WIKI_BUNDLE_TOO_LARGE(размер, лимит); WIKI_IO_ERROR

WIKI_PAGE_NOT_FOUND(root — каталог не существует;
                тихий пустой листинг замаскировал бы опечатку в конфиге);
                WIKI_IO_ERROR

module.responsibility:
Применение принятого file map страниц к wiki: валидация,
                      проверки, атомарная запись, приёмочные строки (FR-21;
                      детерминированный шаг без LLM — файлы следствие артефактов)

task.outputs:
int (exit code): цикл «действие → выполнение → меню» до выхода;
                 действия: запустить цех (выбор цеха, режим autopilot при наличии,
                 вход текстом или путём), статус проектов, wiki-check, выход

task.inputs:
start_run(shop: ShopInfo, input_material: str,
                mode: interactive|autopilot, project: str | None);
                get_state(run_id); pending(run_id); decide(run_id, decision)

task.outputs:
start_run → Result[run_id]; get_state → Result[RunState:
                 running | awaiting_decision | awaiting_answer |
                 done(артефакты) | rejected(причина — REJECTED_BY_USER это
                 решение пользователя, не сбой) | failed(код, причина);
                 для живых статусов — последний узел/итерация ПО ЖУРНАЛУ прогона
                 (записи после offset старта: журнал project общий, прошлые
                 прогоны не подмешиваются)];
                 pending → Result[PendingInteraction(вид, отчёты+артефакт | вопрос)];
                 decide → Result[None] — решение уходит в очередь QueueHITL

task.errors:
RUN_IN_PROGRESS(project — уже есть живой прогон);
                UNKNOWN_RUN(run_id); NO_PENDING_INTERACTION(run_id);
                WRONG_DECISION_KIND(answer на гейт / accept на вопрос)

UNKNOWN_SHOP(имя не в реестре); UNKNOWN_PROJECT(нет в projects/);
                WIKI_REF_ESCAPES_ROOT(ref выходит за корень wiki — недоверенный
                ввод внешней LLM);
                INPUT_FILE_FORBIDDEN(input_material похож на путь, но файл вне
                корня фабрики или скрытый — .env и т.п. читать запрещено;
                существующий разрешённый файл читается как в CLI: смоук MCP
                09.07.2026 показал, что клиенты передают пути — без резолва
                конвейер получает строку пути вместо ТЗ);
                + коды обёрнутых задач фабрики

task.outputs:
Result[str] — нумерованные результаты «заголовок / URL / сниппет»
                 (+ answer провайдера первой строкой, если есть);
                 пусто → Ok("Ничего не найдено.")

Result[list[ToolSpec]] — для "web_search": схема
                 (query обязателен, max_results опционален) и исполнитель;
                 исполнитель ошибки поиска возвращает ТЕКСТОМ
                 («ОШИБКА ПОИСКА …») — сбой провайдера не роняет прогон (TSK-0402);
                 пустой names → Ok([])

task.inputs:
raw: str; chunk_chars: int (дефолт 4000);
                fetcher: Fetcher | None (None → HttpxFetcher; инъекция в тестах,
                образец SearchClient TSK-2101)

task.errors:
MATERIAL_EMPTY (пустой вход); MATERIAL_FETCH_FAILED(url, причина —
                прогон падает явно, битую ссылку убирает пользователь);
                MATERIAL_TOO_LARGE(документ > лимита загрузки)

task.outputs:
build_material_tools(store) → list[ToolSpec];
                 material_search: топ-k «id | заголовок | фрагмент», нули отброшены,
                 пусто → «Ничего не найдено»; material_get: полный текст чанка

task.purpose:
Обвязка пайплайна: материал инжестится один раз на прогон;
                 маленький вход идёт узлам инлайном как раньше, большой
                 заменяется оглавлением + инструкцией читать через material_*

task.outputs:
build_wiki_tools(store) → [wiki_search, wiki_get];
                 wiki_get возвращает страницу целиком (конвенция ≤80 строк);
                 стор строится в _build_node_tools при первом запросе имён

task.inputs:
env BGE_M3_SERVICE_URL (задан → векторный ретривер, пуст →
                LexicalRetriever; образец ключей TAVILY_API_KEY);
                encode-клиент инжектируется в тестах (образец FakeSearch)

MaterialConfig.inline_limit_chars: int (ge=0; 0 — только TOC);
                содержимое чанков доходит до модели через tool-результаты
                (messages), минуя сборку шаблона — искажений нет

task.purpose:
Источники элементов: (а) файлы по glob — элемент = файл;
                 (б) таблицы schema.yaml (PyYAML) — элемент = YAML-фрагмент
                 одной таблицы + её карточка из table_cards (если есть)

task.outputs:
Result[MapReport(rows: [(slug, status, details)], summary_path)];
                 ошибка одного элемента НЕ останавливает остальные —
                 статус failed в сводке

task.purpose:
ToolSpec browser_screenshot для tool-цикла + wiring в
                 workshop_node (имя в config.tools, реестр локальных имён);
                 сбои — ТЕКСТОМ модели (контракт TSK-0402)

task.outputs:
текст: путь сохранённого PNG + title + console errors;
                 имена файлов shot_NNN.png — счётчик без перезаписи
                 существующих (без таймстемпов — воспроизводимость NFR-04)

формат идентификатора и правило связывания находки с TH-id;
                 решение по открытому вопросу №3 ТЗ (блокировать приёмку
                 или накапливать как вход следующей итерации модели угроз)

